function mount(ctx){
  const {root,el,state,ui,size,day,update,runAsync,fetchSource}=ctx;
  const h=(tag,attrs,list)=>el.apply(null,[tag,attrs].concat(list.filter(Boolean)));
  const job=(ui.jobs&&ui.jobs.weather)||null;
  const snap=(state&&state.snap)||null;
  const cur=(job&&job.status==='ok'&&job.data)||snap;
  const data=cur&&cur.data?cur.data:null;
  const at=cur&&cur.at?cur.at:null;
  const loading=!!job&&job.status==='loading';
  const failed=!!job&&job.status==='error';
  const compact=size==='3x3'||size==='3x6';
  const reason=failed?errText(job.error):'';

  const loadWeather=async()=>{
    const d=await fetchSource(WX_SRC);
    const rec={data:d,at:new Date().toISOString()};
    try{await update(s=>Object.assign({},s,{snap:rec}));}catch(e){}
    return rec;
  };
  const refresh=()=>{
    if(loading)return;
    if(ui.jobs)delete ui.jobs.weather;
    runAsync('weather',loadWeather);
  };

  const refreshBtn=el('button',{class:'refresh'+(loading?' busy':''),type:'button','aria-label':'刷新杭州天气',disabled:loading,onclick:refresh},
    el('span',{class:'ri'},'↻'),el('span',{class:'rt'},'刷新'));
  const pill=loading?el('span',{class:'pill'},'更新中…'):failed?el('span',{class:'pill err'},'⚠ 获取失败'):null;
  const top=h('div',{class:'top'},[el('span',{class:'city'},'杭州',el('span',{class:'cw'},'天气')),el('span',{class:'sp'}),pill,refreshBtn]);

  let body;
  if(!data){
    body=h('div',{class:'empty'},[
      el('div',{class:'big'},loading?'正在获取杭州天气…':'暂时获取不到杭州天气'),
      el('div',{class:'sub'},loading?'请稍候':failed?'原因：'+reason:'尚未获取到数据'),
      loading?null:el('button',{class:'btn',type:'button',onclick:refresh},'重试')
    ]);
  }else{
    const temp=fmtTemp(data.temperature);
    const wx=pick(data.weather);
    const wind=fmtWind(data);
    const today=day();
    const all=(Array.isArray(data.forecast)?data.forecast:[]).filter(f=>f&&dayParts(f.date));
    all.sort((a,b)=>dayParts(a.date).key<dayParts(b.date).key?-1:1);
    const todayRow=all.find(f=>dayParts(f.date).key===today);
    const future=all.filter(f=>dayParts(f.date).key>today).slice(0,3);
    const lo=todayRow?fmtTemp(todayRow.temp_min):null,hi=todayRow?fmtTemp(todayRow.temp_max):null;
    const rng=size!=='3x3'&&(lo!==null||hi!==null)?'今日 '+(lo===null?'--':lo)+'° ~ '+(hi===null?'--':hi)+'°':null;
    const now=el('div',{class:'now'},
      el('div',{class:'tempRow'},el('div',{class:'temp'},temp===null?'--':temp,el('span',{class:'deg'},'°')),wxIcon(el,wx)),
      h('div',{class:'facts'},[
        el('div',{class:'wx'},wx===null?'天气未知':String(wx)),
        el('div',{class:'wind'},el('span',{class:'k'},'风'),wind||'暂无'),
        rng?el('div',{class:'rng'},rng):null
      ]));
    const dayEl=f=>{
      const lb=dayLabel(f.date,today),a=fmtTemp(f.temp_max),b=fmtTemp(f.temp_min),w=pick(f.weather_day);
      return el('div',{class:'day'},
        el('div',{class:'dl'},el('span',{class:'da'},lb.a),el('span',{class:'dd'},lb.b)),
        el('div',{class:'dw'},wxIcon(el,w),el('span',{class:'dt'},w===null?'—':String(w))),
        el('div',{class:'dr','aria-label':'最高'+(a===null?'未知':a+'度')+'，最低'+(b===null?'未知':b+'度')},
          el('span',{class:'hi'},(a===null?'--':a)+'°'),el('span',{class:'lo'},'/ '+(b===null?'--':b)+'°')));
    };
    const fc=size==='3x3'?null:el('section',{class:'fc','aria-label':'未来三天'},
      el('div',{class:'fch'},el('b',{},'未来三天'),el('span',{},'最高 / 最低')),
      el('div',{class:'days'},future.length?future.map(dayEl):el('div',{class:'nofc'},'暂无未来预报数据')));
    body=h('div',{class:'body'},[now,fc]);
  }

  const lines=[];
  if(data){
    const t=fmtTime(data.report_time,compact);
    lines.push(el('div',{},(failed?'旧数据 · 更新 ':'数据更新 ')+(t||'时间未知')));
    const l=size==='6x6'&&at?fmtTime(at,false):null;
    if(l)lines.push(el('div',{},'本机获取 '+l));
  }else lines.push(el('div',{},'更新时间：暂无'));
  const note=failed&&data?el('div',{class:'note',title:reason},'刷新失败，显示上次成功数据（'+reason+'）'):null;
  const meta=h('div',{class:'meta'},[note].concat(lines));

  root.append(top,body,meta);

  if(!job)Promise.resolve().then(()=>{if(!(ui.jobs&&ui.jobs.weather))refresh();});
}

